  virtual std::any parseWsBidAsk(std::any ticker,
                                 std::any market = std::any{}) {
    std::any marketId =
        this->safeString(ticker, std::string("instrument_name"));
    market = this->safeMarket(marketId, market);
    std::any symbol = this->safeString(market, std::string("symbol"));
    std::any timestamp = this->safeInteger(ticker, std::string("timestamp"));
    return this->safeTicker(
        ccxt::dict{
            {std::string("symbol"), symbol},
            {std::string("timestamp"), timestamp},
            {std::string("datetime"), this->iso8601(timestamp)},
            {std::string("ask"),
             this->safeString(ticker, std::string("best_ask_price"))},
            {std::string("askVolume"),
             this->safeString(ticker, std::string("best_ask_amount"))},
            {std::string("bid"),
             this->safeString(ticker, std::string("best_bid_price"))},
            {std::string("bidVolume"),
             this->safeString(ticker, std::string("best_bid_amount"))},
            {std::string("info"), ticker},
        },
        market);
  }

